// One definition of how the Communitas library is built from its YAML sources.
// Two call sites: sync-library.mjs (writes the JSON the Worker bundles) and
// site/test/unit/l5/communitas-library.test.ts (fails when the JSON drifts).
// The YAML parser is passed in, so this file has no dependency of its own.

export const SOURCES = {
  threadsYaml: "data/communitas/threads.yaml",
  slackYaml: "data/communitas/slack.yaml",
  dwarvesYaml: "data/team/dwarves.yaml",
};

export const OUTPUT = "workers/communitas/src/generated/library.json";

const NOTE =
  "Generated by workers/communitas/scripts/sync-library.mjs from data/communitas/threads.yaml, " +
  "data/communitas/slack.yaml and data/team/dwarves.yaml. Do not edit. Edit the YAML, then re-run the script.";

function disclosureOf(dwarves, id) {
  const dwarf = Array.isArray(dwarves) ? dwarves.find((d) => d && d.id === id) : undefined;
  if (!dwarf || typeof dwarf.disclosure !== "string" || dwarf.disclosure.length === 0) {
    throw new Error(`data/team/dwarves.yaml has no disclosure for "${id}"`);
  }
  return dwarf.disclosure;
}

export function buildLibrary({ threadsYaml, slackYaml, dwarvesYaml }, parse) {
  const dwarves = parse(dwarvesYaml);
  return {
    _generated: NOTE,
    threads: parse(threadsYaml),
    slack: parse(slackYaml),
    disclosure: {
      communitas: disclosureOf(dwarves, "communitas"),
      resourcus: disclosureOf(dwarves, "resourcus"),
    },
  };
}

export function renderLibrary(library) {
  return `${JSON.stringify(library, null, 2)}\n`;
}
